}

const App: React.FC = () => {
  const [step, setStep] = useState<Step>(Step.LANDING);
  const [userContext, setUserContext] = useState<UserContext>({ name: '', question: '', situation: '', mbti: undefined });
  const [lines, setLines] = useState<LineValue[]>([]);
