              scale: 2,
              backgroundColor: '#1f1b15', 
              useCORS: true,
              logging: false,
              allowTaint: true,
              height: element.scrollHeight,
              windowHeight: element.scrollHeight
          });

          const imgData = canvas.toDataURL('image/jpeg', 0.8);
          const imgWidth = 210; 
          const pageHeight = (canvas.height * imgWidth) / canvas.width;

          const pdf = new jsPDF({
            orientation: 'p',
            unit: 'mm',
