              scale: 2, // High resolution
              backgroundColor: '#2a261f', // Match background
              useCORS: true,
              logging: false,
              allowTaint: true,
              // Force full height capture regardless of scroll position
              height: element.scrollHeight,
              windowHeight: element.scrollHeight,
              y: 0,
              scrollY: 0,
