import React, { useState, useEffect } from 'react';
import { CoinAnimation } from './components/CoinAnimation';
import { HexagramDisplay } from './components/HexagramDisplay';
import { JournalMode } from './components/JournalMode';
import { ProgramMode } from './components/ProgramMode';
import { interpretHexagram, interpretPremiumQuestions } from './services/geminiService';
import { UserContext, LineValue, AnalysisResult } from './types';

enum PremiumStep {
  INPUT = 'INPUT',
  ANALYZING = 'ANALYZING',
  RESULT = 'RESULT'
}

const App: React.FC = () => {
  // --- STATE ---
  const [step, setStep] = useState<'INPUT' | 'TOSSING' | 'ANALYZING' | 'RESULT'>('INPUT');
  const [userContext, setUserContext] = useState<UserContext>({
    name: '',
    question: '',
    situation: '',
    mbti: ''
  });

  // Coin Toss
  const [lines, setLines] = useState<LineValue[]>([]);
  const [isTossing, setIsTossing] = useState(false);
  const [currentResult, setCurrentResult] = useState<[number, number, number]>();

  // Analysis
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);

  // Premium Mode
  const [showPremium, setShowPremium] = useState(false);
  const [premiumStep, setPremiumStep] = useState<PremiumStep>(PremiumStep.INPUT);
  const [premiumQuestions, setPremiumQuestions] = useState({ q1: '', q2: '' });
  const [premiumAdvice, setPremiumAdvice] = useState<string | null>(null);

  // Other Modes
  const [showJournal, setShowJournal] = useState(false);
  const [showProgram, setShowProgram] = useState(false);

  // --- HANDLERS ---

  const handleStart = () => {
    if (!userContext.name || !userContext.question) {
      alert("이름과 질문을 입력해주세요.");
      return;
    }
    setStep('TOSSING');
  };

  const handleToss = () => {
    if (isTossing || lines.length >= 6) return;

    setIsTossing(true);
    // 2 = Tail (Yin), 3 = Head (Yang)
    // Probability: 50/50 for each coin
    const c1 = Math.random() < 0.5 ? 2 : 3;
    const c2 = Math.random() < 0.5 ? 2 : 3;
    const c3 = Math.random() < 0.5 ? 2 : 3;
    setCurrentResult([c1, c2, c3]);
  };

  const handleTossComplete = () => {
    setIsTossing(false);
    if (currentResult) {
      const sum = currentResult.reduce((a, b) => a + b, 0) as LineValue;
      setLines(prev => [...prev, sum]);
    }
  };

  useEffect(() => {
    if (lines.length === 6 && step === 'TOSSING') {
      analyzeResult();
    }
  }, [lines, step]);

  const analyzeResult = async () => {
    setStep('ANALYZING');
    try {
      const result = await interpretHexagram(userContext, lines);
      setAnalysis(result);
      setStep('RESULT');
    } catch (e) {
      console.error(e);
      alert("분석 중 오류가 발생했습니다.");
      setStep('INPUT');
      setLines([]);
    }
  };

  // [TEST ONLY] Bypass Payment with Auto-fill
  const handleTestPremiumAnalyze = async () => {
      // 1. Auto-fill dummy questions if empty
      const currentQ1 = premiumQuestions.q1 || "지금 하는 일이 저에게 맞는 길일까요?";
      const currentQ2 = premiumQuestions.q2 || "앞으로 1년 안에 어떤 변화를 주는 게 좋을까요?";

      setPremiumQuestions({ q1: currentQ1, q2: currentQ2 });

      if (!analysis) {
          alert("먼저 메인 점괘 분석을 완료해주세요.");
          return;
      }

      setPremiumStep(PremiumStep.ANALYZING);

      try {
          // Pass the filled questions directly
          const result = await interpretPremiumQuestions(
              userContext, 
              analysis, 
              { q1: currentQ1, q2: currentQ2 }, 
              lines
          );
          setPremiumAdvice(result);
          setPremiumStep(PremiumStep.RESULT);
      } catch (e) {
          console.error(e);
          alert("분석 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.");
          setPremiumStep(PremiumStep.INPUT);
      }
  };

  const resetAll = () => {
    setStep('INPUT');
    setLines([]);
    setAnalysis(null);
    setPremiumAdvice(null);
    setPremiumStep(PremiumStep.INPUT);
    setPremiumQuestions({ q1: '', q2: '' });
  };

  // --- RENDERING ---

  if (showJournal && analysis) {
    return <JournalMode userContext={userContext} analysis={analysis} onClose={() => setShowJournal(false)} />;
  }

  if (showProgram) {
    return <ProgramMode userContext={userContext} lines={lines} onClose={() => setShowProgram(false)} />;
  }

  return (
    <div className="min-h-screen bg-[#0f172a] text-[#eebd2b] font-serif overflow-y-auto">
      {/* HEADER */}
      <header className="p-6 flex justify-between items-center border-b border-[#eebd2b]/20">
        <h1 className="text-xl font-bold tracking-widest cursor-pointer" onClick={resetAll}>OPPAJEOM</h1>
        {step === 'RESULT' && (
             <div className="flex gap-4">
                 <button onClick={() => setShowJournal(true)} className="text-sm hover:text-white transition-colors">저널</button>
                 <button onClick={() => setShowProgram(true)} className="text-sm hover:text-white transition-colors">구독</button>
             </div>
        )}
      </header>

      <main className="max-w-md mx-auto p-6 flex flex-col items-center min-h-[80vh]">

        {/* STEP 1: INPUT */}
        {step === 'INPUT' && (
          <div className="w-full space-y-6 animate-fade-in pt-10">
            <div className="text-center space-y-2">
              <h2 className="text-2xl font-bold text-white">마음의 준비</h2>
              <p className="text-sm text-gray-400">당신의 고민을 주역에게 물어보세요.</p>
            </div>

            <div className="space-y-4">
               <input 
                 type="text" 
                 placeholder="이름" 
                 className="w-full bg-white/5 border border-[#eebd2b]/30 rounded-lg p-4 text-white focus:outline-none focus:border-[#eebd2b]"
                 value={userContext.name}
                 onChange={e => setUserContext({...userContext, name: e.target.value})}
               />
               <textarea 
                 placeholder="고민이나 질문을 구체적으로 적어주세요." 
