              onClick={handleStart}
              className="w-full bg-[#eebd2b] text-[#0f172a] font-bold py-4 rounded-lg hover:bg-[#ffd54f] transition-colors shadow-lg"
            >
              점괘 보기 시작
            </button>
          </div>
        )}

        {/* STEP 2: TOSSING */}
        {step === 'TOSSING' && (
          <div className="w-full flex flex-col items-center space-y-10 pt-10 animate-fade-in">
             <div className="text-center">
                <h2 className="text-xl font-bold text-white mb-2">동전 던지기 ({lines.length}/6)</h2>
                <p className="text-sm text-gray-400">마음을 담아 동전을 던져주세요.</p>
             </div>

             <HexagramDisplay lines={lines} animateLast={true} />

             <div className="h-40 w-full flex justify-center items-center">
                <CoinAnimation 
                  isTossing={isTossing} 
