             <button 
               onClick={handleToss}
               disabled={isTossing || lines.length >= 6}
               className="w-full max-w-xs bg-[#eebd2b] text-[#0f172a] font-bold py-4 rounded-full hover:bg-[#ffd54f] disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-[0_0_20px_rgba(238,189,43,0.3)]"
             >
