          </div>
        )}

        {/* STEP 3: ANALYZING */}
        {step === 'ANALYZING' && (
           <div className="flex flex-col items-center justify-center pt-32 animate-pulse">
              <span className="material-symbols-outlined text-6xl text-[#eebd2b] mb-4">auto_awesome</span>
              <p className="text-lg text-white font-light">하늘의 뜻을 해석하고 있습니다...</p>
