import { ProgramMode } from './components/ProgramMode';

function App() {
  const [step, setStep] = useState<'INPUT' | 'TOSSING' | 'ANALYZING' | 'RESULT' | 'JOURNAL' | 'PROGRAM'>('INPUT');
  const [user, setUser] = useState<UserContext>({ name: '', question: '', situation: '', mbti: '' });
  const [lines, setLines] = useState<LineValue[]>([]);
  const [tossResult, setTossResult] = useState<[number, number, number] | undefined>(undefined);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [isTossing, setIsTossing] = useState(false);

  // Input Handlers
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setUser(prev => ({ ...prev, [name]: value }));
  };

  const startTossing = () => {
    if (!user.name || !user.question) {
      alert("이름과 질문을 입력해주세요.");
      return;
    }
    setStep('TOSSING');
    tossCoin();
  };

  const tossCoin = () => {
    setIsTossing(true);
    // Random 2 (Tail/Yin) or 3 (Head/Yang) for 3 coins
    // Logic: 
    // 2 (Tail), 3 (Head)
    // Sums: 6(2+2+2), 7(2+2+3), 8(2+3+3), 9(3+3+3)
    const c1 = Math.random() > 0.5 ? 3 : 2;
    const c2 = Math.random() > 0.5 ? 3 : 2;
    const c3 = Math.random() > 0.5 ? 3 : 2;

    // Slight delay to allow animation to start
    setTimeout(() => {
        setTossResult([c1, c2, c3]);
    }, 100);
  };

  const handleTossComplete = async () => {
    setIsTossing(false);
    if (!tossResult) return;

    const sum = (tossResult[0] + tossResult[1] + tossResult[2]) as LineValue;
    const newLines = [...lines, sum];
    setLines(newLines);

    if (newLines.length < 6) {
      setTimeout(() => {
        tossCoin();
      }, 500);
    } else {
      setStep('ANALYZING');
      try {
        const result = await interpretHexagram(user, newLines);
        setAnalysis(result);
        setStep('RESULT');
      } catch (e) {
        console.error(e);
        alert("해석 중 오류가 발생했습니다.");
        setStep('INPUT');
        setLines([]);
      }
    }
  };

  const reset = () => {
    setStep('INPUT');
    setLines([]);
    setAnalysis(null);
    setUser(prev => ({ ...prev, question: '', situation: '' }));
  };

  return (
    <div className="min-h-screen bg-[#1a1a1a] text-white font-sans selection:bg-[#eebd2b] selection:text-black flex flex-col">
