        {/* Header */}
        <header className="mb-8 text-center">
            <div className="inline-block p-3 rounded-full border border-[#eebd2b]/30 mb-4">
                <span className="material-symbols-outlined text-3xl text-[#eebd2b]">yin_yang</span>
            </div>
            <h1 className="text-2xl font-serif font-bold tracking-widest text-[#eebd2b]">OPPAJEOM</h1>
            <p className="text-xs text-gray-500 tracking-[0.3em] mt-1 uppercase">Digital I Ching</p>
        </header>

        {step === 'INPUT' && (
          <div className="w-full space-y-6 animate-fade-in">
             <div className="space-y-4">
                <div>
                    <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider">Name</label>
                    <input 
                        name="name"
                        value={user.name}
                        onChange={handleInputChange}
                        className="w-full bg-white/5 border border-white/10 rounded-lg p-4 text-white placeholder-gray-600 focus:border-[#eebd2b] focus:ring-1 focus:ring-[#eebd2b] outline-none transition-all"
                        placeholder="이름을 알려주세요"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider">MBTI (Optional)</label>
                    <input 
                        name="mbti"
                        value={user.mbti}
                        onChange={handleInputChange}
                        className="w-full bg-white/5 border border-white/10 rounded-lg p-4 text-white placeholder-gray-600 focus:border-[#eebd2b] focus:ring-1 focus:ring-[#eebd2b] outline-none transition-all uppercase"
                        placeholder="예: INFJ"
                        maxLength={4}
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider">Question</label>
                    <textarea 
                        name="question"
                        value={user.question}
                        onChange={handleInputChange}
                        className="w-full bg-white/5 border border-white/10 rounded-lg p-4 h-32 text-white placeholder-gray-600 focus:border-[#eebd2b] focus:ring-1 focus:ring-[#eebd2b] outline-none transition-all resize-none"
                        placeholder="무엇이 고민이신가요? 구체적으로 적을수록 더 정확한 답을 얻을 수 있습니다."
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-wider">Situation (Optional)</label>
                    <textarea 
                        name="situation"
                        value={user.situation}
                        onChange={handleInputChange}
                        className="w-full bg-white/5 border border-white/10 rounded-lg p-4 h-24 text-white placeholder-gray-600 focus:border-[#eebd2b] focus:ring-1 focus:ring-[#eebd2b] outline-none transition-all resize-none"
                        placeholder="현재 상황에 대해 추가로 설명하고 싶은 내용이 있다면 적어주세요."
                    />
                </div>
             </div>

             <button 
