             >
                <span className="material-symbols-outlined">casino</span>
                점괘 보기
             </button>

             <div className="pt-4 text-center">
                 <button onClick={() => setStep('PROGRAM')} className="text-xs text-gray-500 hover:text-[#eebd2b] underline">
                     이미 구독 중이신가요? (프로그램 입장)
                 </button>
             </div>
          </div>
        )}

        {step === 'TOSSING' && (
          <div className="w-full flex flex-col items-center justify-center space-y-12 animate-fade-in">
             <div className="text-center space-y-2">
                 <h2 className="text-xl font-serif text-[#eebd2b]">운명의 동전을 던집니다</h2>
                 <p className="text-sm text-gray-500">{lines.length + 1}번째 효를 구하는 중...</p>
             </div>

             <CoinAnimation 
                isTossing={isTossing} 
                onTossComplete={handleTossComplete}
                result={tossResult}
             />

             <div className="w-full max-w-xs opacity-50 pointer-events-none">
                <HexagramDisplay lines={lines} animateLast={true} />
             </div>
          </div>
        )}

        {step === 'ANALYZING' && (
            <div className="w-full flex flex-col items-center justify-center space-y-6 animate-fade-in">
                <div className="relative w-20 h-20">
                    <div className="absolute inset-0 border-4 border-[#eebd2b]/20 rounded-full"></div>
                    <div className="absolute inset-0 border-4 border-[#eebd2b] border-t-transparent rounded-full animate-spin"></div>
                </div>
                <p className="text-[#eebd2b] font-serif tracking-widest animate-pulse">하늘의 뜻을 읽고 있습니다...</p>
            </div>
        )}

        {step === 'RESULT' && analysis && (
          <div className="w-full animate-fade-in pb-10">
              <div className="bg-[#2a2a2a] p-8 rounded-2xl border border-white/5 shadow-2xl space-y-8">
                  <div className="text-center space-y-2 border-b border-white/10 pb-6">
                      <h2 className="text-3xl font-serif font-bold text-white">{analysis.hexagram.name}</h2>
                      <p className="text-sm text-[#eebd2b] tracking-wider">{analysis.hexagram.hanja}</p>
                  </div>

                  <div className="py-4">
                      <HexagramDisplay lines={lines} animateLast={false} />
                  </div>

                  <div className="space-y-2">
                      <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest text-center mb-4">Core Message</h3>
                      <div className="grid gap-2">
                          {analysis.coreSummary.map((item, idx) => (
                              <div key={idx} className="bg-white/5 rounded-lg p-3 text-sm text-gray-300 text-center border border-white/5">
