                  <div className="space-y-4 pt-4 border-t border-white/10">
                       <h3 className="text-xs font-bold text-[#eebd2b] uppercase tracking-widest">전략적 조언 (Strategic Advice)</h3>
                       <div className="prose prose-invert prose-sm max-w-none">
                           <p className="whitespace-pre-wrap leading-7 text-gray-300 font-light">
