            setSubscription(mockSub);
            setView('WEEKLY_VIEW');
            setIsGenerating(false);
            return;
        }

        const hexagramCode = lines.map(l => (l % 2 !== 0 ? '1' : '0')).join('');
        const movingLines = lines
            .map((l, i) => (l === 6 || l === 9 ? i : -1))
            .filter(i => i !== -1);

        const mockSub: Subscription = {
            id: 'test-uuid-manual',
            user_name: userContext.name || 'Test User',
