                                <div key={i} className="w-full h-2.5 flex justify-between">
                                    <div className="w-[45%] h-full bg-[#D4AF37] rounded-sm shadow-[0_0_2px_rgba(212,175,55,0.2)]"></div>
                                    <div className="w-[45%] h-full bg-[#D4AF37] rounded-sm shadow-[0_0_2px_rgba(212,175,55,0.2)]"></div>
                                </div>
                            )
                    ))}
                </div>
            </div>
        );
    };

