export const ProgramMode: React.FC<ProgramModeProps> = ({ userContext, lines, onClose, initialView = 'ONBOARDING' }) => {
    // Flow: ONBOARDING (Sales Page) -> LOGIN (Phone Input) -> PAYMENT (If new) -> WEEKLY_VIEW
    const [view, setView] = useState<'ONBOARDING' | 'LOGIN' | 'WEEKLY_VIEW'>(initialView);
    const [phone, setPhone] = useState('');
    const [subscription, setSubscription] = useState<Subscription | null>(null);
    const [weeklyContent, setWeeklyContent] = useState<WeeklyContent | null>(null);
    const [lineCommentary, setLineCommentary] = useState<string>("");

    // Inputs
    const [emotionInput, setEmotionInput] = useState('');
    const [reviewInput, setReviewInput] = useState(''); // Week 2+ Review Input
    const [prevActionItem, setPrevActionItem] = useState<string | null>(null); // To display previous week's task

    const [isGenerating, setIsGenerating] = useState(false);
    const [isDownloading, setIsDownloading] = useState(false); 

    // [UX Enhancement] Scroll Lock Logic
    useEffect(() => {
        document.body.style.overflow = 'hidden';
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, []);

    // [Restore Logic] Restore phone from session storage if returning from payment
    useEffect(() => {
        const savedContext = JSON.parse(sessionStorage.getItem('oppajeom_context') || '{}');
        const savedIsProgramMode = sessionStorage.getItem('oppajeom_is_program_mode') === 'true';

        // If we are in ProgramMode restoration context and have phone info in context(optional) or separate storage
        // Assuming userContext.name is reliable.
        // For simplicity, we just check if subscription check is needed.
        if (savedIsProgramMode && savedContext.name) {
             // We can't automatically fill phone unless we saved it. 
             // Let's assume user re-enters or we save it.
             // Actually, saving 'phone' to session storage is safe enough for redirect.
             const savedPhone = sessionStorage.getItem('oppajeom_phone');
             if (savedPhone) {
                 setPhone(savedPhone);
                 // Auto-trigger login? Maybe too aggressive. Let user click.
             }
        }
    }, []);

    // --- HANDLERS ---

    const handleLoginAndPay = async (targetPg: string) => {
        if (!phone || phone.length < 10) {
            alert("올바른 전화번호를 입력해주세요.");
            return;
        }

        setIsGenerating(true);

        const sub = await getSubscriptionByPhone(phone);

        if (sub) {
            // Existing User
            setSubscription(sub);

            try {
                // 1. Check if current week content already exists
                const existingLog = await getLogByWeek(sub.id, sub.current_week);
                if (existingLog && existingLog.ai_content) {
                    setWeeklyContent(existingLog.ai_content);
                    if (existingLog.user_emotion) {
                        setEmotionInput(existingLog.user_emotion);
                    }
                } else if (sub.current_week > 1) {
                    // 2. If no content for current week, but week > 1, fetch previous week's ritual for review
                    const prevLog = await getPreviousLog(sub.id, sub.current_week);
                    if (prevLog && prevLog.ai_content) {
                        setPrevActionItem(prevLog.ai_content.action_item);
                    }
                }
            } catch (e) {
                console.error("Failed to fetch log info", e);
            }

            setView('WEEKLY_VIEW');
            setIsGenerating(false);
        } else {
            // New User
            if (lines.length < 6) {
                alert("신규 구독을 위해서는 먼저 점괘(동전 던지기)가 필요합니다.\n메인 화면으로 이동합니다.");
                onClose();
                return;
            }
            requestPayment(targetPg);
        }
    };

    const requestPayment = (targetPg: string) => {
        if (!window.IMP) {
            alert("결제 모듈 로딩 실패");
            setIsGenerating(false);
            return;
        }

        // Ensure Initialization
        window.IMP.init("imp16601765");

        // [FIX] Save State for Redirect
        sessionStorage.setItem('oppajeom_payment_pending', 'true');
        sessionStorage.setItem('oppajeom_context', JSON.stringify(userContext));
        sessionStorage.setItem('oppajeom_lines', JSON.stringify(lines));
        sessionStorage.setItem('oppajeom_is_program_mode', 'true');
        sessionStorage.setItem('oppajeom_phone', phone); // Save phone to auto-fill

        // [FIX] Mobile Optimized Payment Params
        window.IMP.request_pay({
            pg: targetPg,
            pay_method: "card", // Default to card
            merchant_uid: `sub_${new Date().getTime()}`,
            name: "월간 화두: 4주 마음 챙김 구독",
            amount: 9900,
            buyer_email: "from.mr.ouyaa@gmail.com", 
            buyer_name: userContext.name,
            buyer_tel: phone,
            m_redirect_url: window.location.href, // [FIX] Essential for mobile return
            app_scheme: 'oppajeompayment', // [FIX] Required for iOS/Android app switching
            popup: false // [FIX] Force redirect to avoid iframe cutoff on mobile
        }, async (rsp: any) => {
            if (rsp.success) {
                const newSub = await createSubscription(userContext, lines, phone);
                if (newSub) {
                    setSubscription(newSub);
                    await triggerAlimTalk(phone, userContext.name, 1);
                    setView('WEEKLY_VIEW');
                } else {
                    alert("구독 생성 실패. 관리자에게 문의하세요.");
                }
            } else {
                console.warn("Payment failed or cancelled:", rsp);
                if (rsp.error_msg && !rsp.error_msg.includes('취소')) {
                    alert(`결제 실패: ${rsp.error_msg}`);
                }
            }
            setIsGenerating(false);
        });
    };

    const handleTestSubscription = () => {
        if (lines.length < 6) {
            const mockHexagramCode = '111111'; 
            const mockMovingLines: number[] = [];

             const mockSub: Subscription = {
                id: 'test-uuid-manual',
                user_name: 'Test User',
                phone: '01000000000',
                hexagram_code: mockHexagramCode,
                moving_lines: mockMovingLines,
                situation: 'Test Situation',
                started_at: new Date().toISOString(),
                current_week: 1,
                status: 'active'
            };
            setSubscription(mockSub);
            setView('WEEKLY_VIEW');
            setIsGenerating(false);
            return;
        }

        const hexagramCode = lines.map(l => (l % 2 !== 0 ? '1' : '0')).join('');
