            setIsGenerating(false);
        }
    };

    const downloadCard = async () => {
        if (!weeklyContent || !subscription) return;
        const hexCode = subscription.hexagram_code || '111111';
        const hexInfo = HEXAGRAM_TABLE[hexCode] || { name: '중천건', hanja: '重天乾' };

