    if (view === 'WEEKLY_VIEW') {
        // State 1: Before Generation (Input Emotion)
        if (!weeklyContent) {
            const hexCode = subscription?.hexagram_code || '111111';
            const hexInfo = HEXAGRAM_TABLE[hexCode] || { name: '알 수 없음', hanja: '' };
