                        ))}
                    </div>
                </div>
            </div>
        </div>
      )}

      {/* STEP 3: DIVINATION */}
      {step === Step.DIVINATION && (
        <div className="flex flex-col items-center h-screen w-full px-6 pt-6 pb-24 relative">
