        return `${name}의 괘상을 얻으셨군요. 현재 당신의 상황에 이 괘가 가진 고유한 변화의 힘이 작용하고 있습니다.`;
    };

    const formatActionItem = (text: string) => text.replace(/([.?!])\s+/g, "$1\n\n");

    const currentWeek = subscription?.current_week || 1;
